"""Explain user access macros and KCSAN bit budgets for beginners."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1689': ('원래 쪽지에 직접 검사 도장을 찍기 어려우면 임시 쪽지에 내용을 옮겨 검사 표시를 다룬 뒤 되돌릴 수 있어요. 이 코드도 주소를 구할 수 있는 임시 변수를 이용해요.', '임시 변수의 주소를 사용하는 이유와 검사 시점을 이해합니다.', 'to → 64비트 임시 변수 __tmp → 검사 표시 변경 → to 대입을 그리세요. &to 대신 &__tmp를 사용한다고 적으세요.', ['get_user는 사용자 공간의 값을 커널 쪽으로 가져오는 작업과 관련된 이름이에요. instrument_get_user는 그 작업에 KMSAN 검사 정보를 연결하는 매크로예요. 매크로는 호출 모양의 글을 정해진 코드로 펼치는 규칙이며 일반 함수와 같지는 않아요.', '첫 줄 u64 __tmp = (u64)(to)는 to의 값을 64비트 부호 없는 정수로 바꾸어 임시 변수 __tmp에 보관해요. u64는 64개의 이진 칸을 가진 정수 형식이에요. 8비트가 1바이트이므로 크기는 8바이트예요.', '다음 줄은 kmsan_unpoison_memory(&__tmp, sizeof(__tmp))예요. &__tmp는 임시 변수가 있는 주소, sizeof(__tmp)는 그 변수의 크기예요. KMSAN은 값이 준비되지 않은 메모리를 쓰는 실수를 찾고, unpoison은 지정한 범위의 검사 상태를 준비됨으로 바꾸어요. 실제 값을 0으로 지우는 뜻은 아니에요.', '왜 &to를 쓰지 않을까요? 원문의 설명은 to가 주소를 취할 수 없는 변수일 수도 있다고 말해요. 그래서 주소를 구할 수 있는 임시 변수를 만들고 그 주소를 전달해요. 마지막 to = __tmp는 임시 값과 관련된 상태가 원래 변수로 이어지도록 대입하는 단계예요.', '({ ... }) 안에 여러 줄을 묶는 문법은 GNU C의 확장 문법이에요. 이 코드의 to는 값을 읽는 곳과 대입하는 곳에 다시 나타나요. 그러므로 번호를 증가시키는 복잡한 표현식을 넣어도 무조건 한 번만 평가한다고 생각하면 안 돼요. 정해진 사용자 접근 코드의 변수에 맞춰 쓰는 도우미이지 아무 형식의 데이터를 처리하는 일반 복사기가 아니에요.', '실제 사용자 값 복사와 이 검사 표시 작업의 순서는 사용자 접근 구현에 따라 앞일 수도 뒤일 수도 있다고 원문이 설명해요. 모든 CPU에서 반드시 복사 뒤라고 외우면 안 돼요. 주변 호출 코드를 읽어 실제 데이터 이동과 검사 연결이 어디에 놓였는지 확인해야 해요.'], [('이 매크로는 검사 함수에 누구의 주소를 주나요?', ['항상 원래 변수의 주소 &to를 줘요', '임시 변수의 주소 &__tmp를 줘요'], '정답은 두 번째예요. 원래 변수는 주소를 취할 수 없는 경우도 고려해야 하므로 u64 임시 변수를 만들어 그 주소를 사용해요. 본문에는 &to가 없어요.'), ('이 검사는 모든 구현에서 실제 사용자 값 복사 뒤에만 실행되나요?', ['아니요. 사용자 접근 구현에 따라 앞이나 뒤에 놓일 수 있어요', '네. 모든 CPU에서 반드시 복사 뒤예요'], '정답은 첫 번째예요. 원문 주석은 구현에 따라 before 또는 after가 될 수 있다고 설명해요. 함수 이름만으로 시점을 고정하지 말고 호출 순서를 확인해야 해요.')]), 'os1690': ('주문서에 크기 칸이 있어도 담당자가 실제로 쓰는 길이는 물건 자체의 크기일 수 있어요. 이 매크로도 size라는 이름보다 펼쳐진 코드를 확인해야 해요.', '매크로에서 실제로 쓰는 크기와 사용하지 않는 인자를 구별합니다.', 'from이 4바이트 변수일 때 instrument_put_user(from,ptr,99)를 펼쳐 sizeof(from)=4를 표시하세요. 99가 결과 코드에 없는지 찾으세요.', ['put_user는 커널 쪽 값을 사용자 공간에 쓰는 작업과 관련돼요. instrument_put_user(from,ptr,size)는 그 작업에 검사 정보를 연결하는 매크로예요. from은 보낼 값을 가진 변수이고 ptr은 사용자 쪽 도착 주소예요.', '펼쳐지는 핵심 코드는 kmsan_copy_to_user(ptr,&from,sizeof(from),0)이에요. &from은 값을 담은 변수의 주소이고 sizeof(from)은 그 변수 형식의 크기예요. 따라서 from은 주소를 취할 수 있는 대상이어야 해요. 숫자 상수처럼 주소를 취할 수 없는 것을 마음대로 넣을 수는 없어요.', 'from이 4바이트 변수라면 sizeof(from)은 4예요. 바깥에서 size 자리에 99를 적어도 이 본문은 그 99를 사용하지 않아요. 검사 함수에 전달하는 길이는 4이지 99가 아니에요. 이름이 size라고 해서 반드시 길이를 결정하는 것은 아니에요.', '매크로는 인자를 받은 뒤 본문에 필요한 글을 끼워 넣어요. 여기서는 size라는 인자 자리가 본문에 없으므로 size 자리에 직접 쓴 side_effect() 같은 함수 호출도 펼쳐진 코드에서 없어져요. 이 직접 매크로 호출 때문에 그 함수가 실행되지는 않아요.', '이것은 일반 함수 호출과 달라요. 일반 함수에 전달할 값을 계산하는 표현식은 함수 안에서 그 값을 쓰지 않더라도 평가돼요. 예를 들어 바깥 함수에 들어오기 전에 이미 계산된 효과까지 이 매크로가 되돌리는 것은 아니에요. 사용하지 않는 직접 매크로 인자와 앞서 실행된 일을 구별하세요.', '마지막 0도 이 코드가 정해 전달하는 인자예요. 실제 사용자 쓰기의 성공 결과를 여기서 받아 적는 구조는 아니에요. 실제 값 전달과 검사 연결은 별개이고, 이 도우미를 불렀다는 사실만으로 사용자 공간에 쓰기가 끝났다고 판단하면 안 돼요.'], [('from이 4바이트 변수이고 size 자리에 99를 넣었어요. 실제 검사 길이는 얼마인가요?', ['size에 적은 99바이트예요', 'sizeof(from)으로 구한 4바이트예요'], '정답은 두 번째예요. 본문은 size를 쓰지 않고 sizeof(from)을 전달해요. 매크로의 인자 이름만 보지 말고 실제 펼쳐질 식을 읽어야 해요.'), ('이 매크로의 size 자리에 직접 side_effect()를 쓰면 그 호출이 실행되나요?', ['아니요. 사용하지 않는 size 인자는 펼쳐진 코드에 남지 않아요', '네. 일반 함수의 인자처럼 반드시 실행돼요'], '정답은 첫 번째예요. size를 사용하는 자리가 없어서 직접 넣은 호출도 사라져요. 일반 함수에 인자를 전달할 때의 평가 규칙을 이 매크로에 그대로 적용하면 안 돼요.')]), 'os1691': ('검사할 서랍이 세 개라고 해서 물건의 허용 길이도 세 칸인 것은 아니에요. 서랍 개수와 물건 길이는 서로 다른 규칙으로 정해져요.', '검사 슬롯 수와 표현 가능한 접근 길이를 서로 다른 식으로 계산합니다.', 'PAGE_SIZE=4096일 때 길이 4096×(1+1)=8192와 슬롯 수 1+2×1=3을 각각 적으세요.', ['KCSAN은 여러 실행 흐름이 같은 메모리를 다루면서 충돌하는 문제를 찾는 도구예요. watchpoint는 살펴볼 접근의 주소, 길이, 쓰기 여부 같은 정보를 담은 감시 기록이에요. slot은 이런 기록을 넣고 찾아보는 자리예요.', '페이지는 메모리를 일정한 크기로 나눈 덩어리예요. PAGE_SIZE는 한 페이지의 바이트 수예요. 이 코드에서는 SLOT_RANGE가 PAGE_SIZE와 같아요. 이 수업의 4096바이트는 계산을 위한 구성 예시이며 모든 컴퓨터의 페이지 크기가 같다는 뜻은 아니에요.', '표현할 최대 접근 길이 MAX_ENCODABLE_SIZE의 식은 SLOT_RANGE × (1+KCSAN_CHECK_ADJACENT)예요. 고정 원본에서 KCSAN_CHECK_ADJACENT는 1이므로 한 페이지 길이의 두 배예요. 4096×2=8192바이트가 돼요.', '확인할 슬롯 수 NUM_SLOTS의 식은 1+2×KCSAN_CHECK_ADJACENT예요. 자기 자리 하나와 양옆의 인접 자리 하나씩을 합쳐 3이에요. 길이 식의 1+1과 자리 수 식의 1+2×1은 다르므로 3을 페이지 길이에 곱하면 틀려요.', '페이지가 65536바이트인 구성으로 계산하면 최대 길이는 65536×2=131072바이트예요. 인접 설정이 그대로 1이면 확인 슬롯 수는 여전히 3이에요. 이 예는 식을 계산한 것이며 해당 커널 구성을 실제 실행했다는 뜻은 아니에요.', 'check_encodable은 주소가 PAGE_SIZE 이상인지와 길이가 MAX_ENCODABLE_SIZE 이하인지 둘 다 확인해요. 아주 낮은 주소를 제외하는 것은 KCSAN 내부의 잘못된 주소 접근을 피하려는 조건이에요. 이 두 조건을 통과했다고 그 메모리의 수명이나 모든 접근의 안전성이 증명되는 것은 아니에요.'], [('페이지가 4096바이트이고 인접 설정이 1이면 최대 표현 길이는 얼마인가요?', ['슬롯이 3개이므로 4096×3=12288바이트예요', '4096×(1+1)=8192바이트예요'], '정답은 두 번째예요. 최대 길이 식에는 1+인접 설정을 써요. 3은 양옆을 포함해 확인하는 슬롯 개수이지 길이의 페이지 배수가 아니에요.'), ('이 설정에서 확인 슬롯 수와 최대 길이의 페이지 배수는 같은가요?', ['아니요. 슬롯 수는 3이고 길이는 2페이지예요', '네. 둘 다 언제나 3이에요'], '정답은 첫 번째예요. 슬롯 수는 1+2×1=3, 길이의 배수는 1+1=2예요. 무엇을 세는 식인지 먼저 구별해야 해요.')]), 'os1692': ('작은 기록 카드 하나에 쓰기 표시, 길이, 주소를 나눠 적으려고 해요. 한 칸을 다른 항목에 쓰면 주소에 쓸 칸은 그만큼 줄어요.', '비트 수를 나눠 쓰는 원리와 최대값을 포함할 때 필요한 자리 수를 이해합니다.', '64칸을 쓰기 1칸·길이 14칸·주소 49칸으로 나누세요. 13비트 최대 8191과 저장할 값 8192를 비교하세요.', ['비트는 0이나 1을 담는 작은 칸이에요. 1비트에는 두 가지, 2비트에는 00·01·10·11 네 가지 모양을 담을 수 있어요. 숫자로 읽으면 2비트의 범위는 0부터 3까지예요. 칸을 하나 늘릴 때마다 담을 수 있는 모양 수가 두 배가 돼요.', 'watchpoint는 감시할 메모리 접근을 적은 기록이에요. 이 구현은 long 정수 하나에 쓰기 여부, 접근 길이, 주소의 일부를 나누어 담아요. 인코딩은 이 정보를 정해진 자리로 바꾸어 넣는 일이에요. 여러 정보가 서로의 자리를 침범하지 않게 비트 수를 정해야 해요.', '64비트 long과 4096바이트 페이지인 예에서는 최대 길이가 8192예요. 13비트에는 8192가지 모양이 있지만 0부터 세므로 최대 숫자는 8191이에요. 따라서 숫자 8192 자체를 담으려면 한 칸 더 많은 14비트가 필요해요. 모양 개수와 가장 큰 숫자를 구별하세요.', '가장 위 1비트는 쓰기 여부에, 그 아래 14비트는 길이에 써요. 남은 주소 자리는 64-1-14=49비트예요. 주소 전체 64비트가 그대로 보존되는 것은 아니에요. 이 수치는 정한 예시 구성의 결과이고 long 폭이나 페이지 크기가 달라지면 다시 계산해야 해요.', '코드의 size << WATCHPOINT_ADDR_BITS는 길이 값을 왼쪽으로 밀어 길이 칸에 놓는 동작이에요. addr & WATCHPOINT_ADDR_MASK는 주소에서 남길 아래쪽 칸만 골라요. |는 이렇게 겹치지 않게 준비한 비트들을 한 기록으로 합쳐요. 쓰기이면 맨 위 표시를 켜고 읽기이면 끈 상태로 둬요.', '주소의 위쪽 비트를 버리므로 서로 다른 주소가 같은 압축 주소 모양이 될 가능성도 있어요. 이 기록만 보고 원래 전체 주소가 완전히 같다고 단정하면 안 돼요. 원문은 슬롯 배치와 보고 단계의 추가 확인도 함께 고려한다고 설명해요. 압축은 공간을 아끼지만 버린 정보를 이 값 하나에서 되살릴 수는 없어요.'], [('0부터 숫자 8192까지 포함해서 담으려면 몇 비트가 필요한가요?', ['13비트면 돼요', '14비트가 필요해요'], '정답은 두 번째예요. 13비트는 8192가지 모양이지만 숫자로는 0~8191이에요. 8192는 그 범위를 하나 넘어가므로 14번째 자리가 필요해요.'), ('64비트 중 쓰기 표시 1비트와 길이 14비트를 쓰면 주소에는 몇 비트가 남나요?', ['64-1-14=49비트예요', '주소에는 여전히 64비트 전부를 써요'], '정답은 첫 번째예요. 하나의 64비트 기록을 세 항목이 나누어 써요. 이미 15비트를 다른 항목에 썼으므로 주소에 남은 자리는 49비트예요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_418.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
